//! Oracle fuzz test for the original function at 0x103b18 (generated by `factory gen`; the spec is the static
//! scan's inference: fix it here if the original faults or writes past a block). The port is `kh2_factory::ported::set_word_33e78c`.
//! Skips without a disc (KH2_ISO or local/iso.txt); fails without one when KH2_REQUIRE_DISC=1.

use kh2_factory::fuzz::*;

const SPEC: Spec = Spec {
    addr: 0x103b18,
    args: &[Arg::Int(&[])],
    floats: 0,
    ret: Ret::None,
    globals: &[(0x33e78c, 4, true)],
    stubs: &[],
    nulls: true,
};

#[test]
fn orig_103b18_matches_the_game() {
    let Some(st) = fuzz(&SPEC, 4000, |c| {
        let v = c.int(0);
        kh2_factory::ported::set_word_33e78c(c.global(0), v);
        Out::none()
    }) else { return };
    eprintln!("{} cases equal, {} interpreter steps in {:.3} s", st.cases, st.steps, st.secs);
}
